/**
 * Table.Row: a row, a `<tr>`.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/table.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, useContext, type JSX } from 'solid-js'

import { claimSlot, createDerived, ownerContext, scope, type Defaults } from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/table.module.css'
import type { TableOwner } from './Table'

export interface TableRowProps {
  children?: JSX.Element
  /**
   * Adds hover and a pointer cursor; the row's own primary cell still holds the link.
   */
  interactive?: boolean
  onClick?: () => void
  /**
   * Visual only in a table and semantic in a grid, because `aria-selected` belongs to a `grid`.
   * `undefined` is a third value. Rows that never set `aria-selected` mean the grid has no
   * selection, and `aria-selected="false"` means this row is outside an existing selection.
   * Defaulting to `false` would announce every plain table row as unselected, which tells the
   * reader nothing.
   */
  selected?: boolean
}

/** Table.Row: a row, a `<tr>`. */
export default function TableRow(given: TableRowProps): JSX.Element {
  const props = mergeProps(
    { interactive: false } as Defaults<TableRowProps, 'interactive'>,
    claimSlot(given),
  )
  const owner = useContext(ownerContext<TableOwner>('Table')) ?? ({} as TableOwner)
  return scope(() => {
    const open = createDerived(() => (event: KeyboardEvent) => {
      if (
        event.key !== 'Enter' ||
        !(event.target instanceof HTMLElement) ||
        !event.target.matches('th, td')
      )
        return
      event.preventDefault()
      props.onClick?.()
    })
    return (
      <tr
        class={styles.row}
        data-interactive={props.interactive ? '' : undefined}
        data-selected={props.selected ? '' : undefined}
        aria-selected={owner.grid && props.selected !== undefined ? props.selected : undefined}
        onclick={() => props.interactive && props.onClick?.()}
        onkeydown={($event: KeyboardEvent) =>
          owner.grid && props.interactive && props.onClick !== undefined && open.value($event)
        }
      >
        {props.children}
      </tr>
    )
  })
}
